import{_ as a,c as r,o as i,ag as o}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Mobile Hardening Guide","description":"","frontmatter":{"title":"Mobile Hardening Guide"},"headers":[],"relativePath":"general/mobile-hardening-guide.md","filePath":"general/mobile-hardening-guide.md","lastUpdated":null}'),t={name:"general/mobile-hardening-guide.md"};function n(l,e,s,d,p,c){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="mobile-hardening-guide" tabindex="-1">Mobile Hardening Guide <a class="header-anchor" href="#mobile-hardening-guide" aria-label="Permalink to &quot;Mobile Hardening Guide&quot;">​</a></h1><h2 id="mobile-device-hardening-android-ios" tabindex="-1">Mobile Device Hardening: Android | iOS <a class="header-anchor" href="#mobile-device-hardening-android-ios" aria-label="Permalink to &quot;Mobile Device Hardening: Android  |  iOS&quot;">​</a></h2><p>Ensure the safety and security of your mobile devices with these critical guidelines and recommendations tailored for Android and iOS systems. Additional resources are available at the <a href="https://github.com/irregularchat/public-resources/tree/main/Checklists" target="_blank" rel="noreferrer">DFP Checklists</a>.</p><p>There is a larger <a href="/general/dfp-guide.html">Section</a> that is broader than just mobile devices</p><h3 id="nsa-mobile-device-best-practices" tabindex="-1">NSA Mobile Device Best Practices <a class="header-anchor" href="#nsa-mobile-device-best-practices" aria-label="Permalink to &quot;NSA Mobile Device Best Practices&quot;">​</a></h3><p>Download the <a href="#">Mobile Device Best Practices PDF</a> for a comprehensive guide. Below are some essential highlights:</p><ul><li><p><strong>Keep Applications Updated</strong>: Ensure apps are always up-to-date to mitigate vulnerabilities and benefit from the latest security patches.</p></li><li><p><strong>Disable AdTech</strong>: Remove your Advertising ID and disable personalized ads to reduce tracking.</p></li><li><p><strong>Use Screen Lock Protection</strong>: Secure your device with passcodes, fingerprint, or facial recognition.</p></li><li><p><strong>Lock Individual Apps</strong>: Set additional locks for sensitive apps such as those handling communication and finance.</p></li><li><p><strong>Power Cycle Your Device</strong>: Regularly restart your phone to clear out potential vulnerabilities.</p></li></ul><h3 id="comprehensive-mobile-security-checklist" tabindex="-1">Comprehensive Mobile Security Checklist <a class="header-anchor" href="#comprehensive-mobile-security-checklist" aria-label="Permalink to &quot;Comprehensive Mobile Security Checklist&quot;">​</a></h3><p>This checklist is designed to help you harden your mobile device security:</p><p><strong>Digital Security</strong>:</p><ul><li><p>☑ Disable unused wireless radios.</p></li><li><p>☑ Use airplane mode when not needed.</p></li><li><p>☑ Avoid apps and settings that rely heavily on ad tracking.</p></li></ul><p><strong>Passwords &amp; Authentication</strong>:</p><ul><li><p>☑ Use strong passwords or pins for screen locks.</p></li><li><p>☑ Lock your SIM card and obtain the PUK from your carrier.</p></li><li><p>☑ Enable device encryption.</p></li><li><p>☑ Use biometrics wisely (prefer non-index fingers).</p></li><li><p>☑ Use a trusted password manager.</p></li></ul><p><strong>Activity &amp; Maintenance</strong>:</p><ul><li><p>☑ Turn off always-on virtual assistants.</p></li><li><p>☑ Regularly update the OS and apps.</p></li><li><p>☑ Avoid public USB chargers; use data blockers.</p></li><li><p>☑ Download apps only from trusted sources.</p></li><li><p>☑ Use a VPN and enable password protection for vital apps.</p></li><li><p>☑ Maximize privacy settings in all apps.</p></li></ul><h3 id="mobile-applications-for-enhancing-security-and-privacy" tabindex="-1">Mobile Applications for Enhancing Security and Privacy <a class="header-anchor" href="#mobile-applications-for-enhancing-security-and-privacy" aria-label="Permalink to &quot;Mobile Applications for Enhancing Security and Privacy&quot;">​</a></h3><p>Here are some recommended applications to strengthen your mobile device&#39;s security and privacy:</p><h3 id="side-loading-apps-risks-and-benefits-android" tabindex="-1">Side-Loading Apps: Risks and Benefits (Android) <a class="header-anchor" href="#side-loading-apps-risks-and-benefits-android" aria-label="Permalink to &quot;Side-Loading Apps: Risks and Benefits (Android)&quot;">​</a></h3><p>Understand the pros and cons of side-loading apps (installing from non-official sources):</p><h4 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h4><ul><li><p>Access a broader range of apps.</p></li><li><p>Use open-source apps for better privacy.</p></li></ul><h4 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h4><ul><li><p>Potential exposure to malware.</p></li><li><p>May void your device&#39;s warranty.</p></li></ul><h3 id="f-droid-a-secure-alternative" tabindex="-1">F-Droid: A Secure Alternative <a class="header-anchor" href="#f-droid-a-secure-alternative" aria-label="Permalink to &quot;F-Droid: A Secure Alternative&quot;">​</a></h3><p>F-Droid is an open-source platform for Android apps that focuses on privacy and security.</p><h4 id="pros" tabindex="-1">Pros <a class="header-anchor" href="#pros" aria-label="Permalink to &quot;Pros&quot;">​</a></h4><ul><li><p>Non-tracking, privacy-first app store.</p></li><li><p>Access to open-source apps.</p></li></ul><h4 id="cons" tabindex="-1">Cons <a class="header-anchor" href="#cons" aria-label="Permalink to &quot;Cons&quot;">​</a></h4><ul><li><p>Limited selection compared to Google Play.</p></li><li><p>Possible compatibility issues on some devices.</p></li></ul><h3 id="how-to-install-f-droid" tabindex="-1">How to Install F-Droid <a class="header-anchor" href="#how-to-install-f-droid" aria-label="Permalink to &quot;How to Install F-Droid&quot;">​</a></h3><ol><li>Visit the <a href="https://f-droid.org/en/" target="_blank" rel="noreferrer">official F-Droid website</a>.</li><li>Download the F-Droid APK file.</li><li>Enable installation from unknown sources on your Android device.</li><li>Open the APK file to install F-Droid.</li><li>Browse and install secure, open-source apps.</li></ol><p>For those looking for a Google Play alternative, try the <a href="https://f-droid.org/en/packages/com.aurora.store/" target="_blank" rel="noreferrer">Aurora Store</a>, an open-source frontend to Google Play with privacy in mind.</p><h3 id="recommended-mobile-apps-for-security-and-privacy-android-and-ios" tabindex="-1">Recommended Mobile Apps for Security and Privacy (Android and iOS) <a class="header-anchor" href="#recommended-mobile-apps-for-security-and-privacy-android-and-ios" aria-label="Permalink to &quot;Recommended Mobile Apps for Security and Privacy (Android and iOS)&quot;">​</a></h3><h4 id="password-management" tabindex="-1">Password Management <a class="header-anchor" href="#password-management" aria-label="Permalink to &quot;Password Management&quot;">​</a></h4><ul><li><p><strong>Bitwarden</strong>: Available on <a href="https://play.google.com/store/apps/details?id=com.x8bit.bitwarden" target="_blank" rel="noreferrer">Android</a> and <a href="https://apps.apple.com/us/app/bitwarden-password-manager/id1137397744" target="_blank" rel="noreferrer">iOS</a>.</p></li><li><p><strong>KeePass</strong>: Available on <a href="https://play.google.com/store/apps/details?id=keepass2android.keepass2android" target="_blank" rel="noreferrer">Android</a>, <a href="https://strongboxsafe.com/" target="_blank" rel="noreferrer">iOS</a>, and <a href="https://f-droid.org/en/packages/com.android.keepass/" target="_blank" rel="noreferrer">F-Droid</a>.</p></li></ul><h4 id="two-factor-authentication" tabindex="-1">Two-Factor Authentication <a class="header-anchor" href="#two-factor-authentication" aria-label="Permalink to &quot;Two-Factor Authentication&quot;">​</a></h4><ul><li><p><strong>Aegis</strong>: Available on <a href="https://getaegis.app/" target="_blank" rel="noreferrer">Android</a> and <a href="https://f-droid.org/en/packages/com.beemdevelopment.aegis/" target="_blank" rel="noreferrer">F-Droid</a>.</p></li><li><p><strong>2FAS</strong>: More details available on the <a href="/general/dfp-guide.html#multi-factor-authentication-mfa">official MFA guide</a>.</p></li></ul><h4 id="malware-protection" tabindex="-1">Malware Protection <a class="header-anchor" href="#malware-protection" aria-label="Permalink to &quot;Malware Protection&quot;">​</a></h4><ul><li><strong>Malwarebytes</strong>: Available on <a href="https://play.google.com/store/apps/details?id=org.malwarebytes.antimalware" target="_blank" rel="noreferrer">Android</a> and <a href="https://apps.apple.com/us/app/malwarebytes-mobile-security/id1327105431" target="_blank" rel="noreferrer">iOS</a>.</li></ul><h4 id="encryption-and-data-protection" tabindex="-1">Encryption and Data Protection <a class="header-anchor" href="#encryption-and-data-protection" aria-label="Permalink to &quot;Encryption and Data Protection&quot;">​</a></h4><ul><li><p><strong>OpenKeychain</strong>: Manage PGP keys on <a href="https://play.google.com/store/apps/details?id=org.sufficientlysecure.keychain" target="_blank" rel="noreferrer">Android</a>.</p></li><li><p><strong>Cryptomator</strong>: Encrypt files before cloud upload on <a href="https://play.google.com/store/apps/details?id=org.cryptomator" target="_blank" rel="noreferrer">Android</a>, <a href="https://apps.apple.com/us/app/cryptomator/id953086535" target="_blank" rel="noreferrer">iOS</a>, and <a href="https://f-droid.org/en/packages/org.cryptomator.lite/" target="_blank" rel="noreferrer">F-Droid</a>.</p></li></ul><h4 id="secure-communication" tabindex="-1">Secure Communication <a class="header-anchor" href="#secure-communication" aria-label="Permalink to &quot;Secure Communication&quot;">​</a></h4><ul><li><p><strong>Element Messenger</strong>: Available on <a href="https://play.google.com/store/apps/details?id=im.vector.app" target="_blank" rel="noreferrer">Android</a> and <a href="https://apps.apple.com/us/app/element-messenger/id1083446067" target="_blank" rel="noreferrer">iOS</a>, also on <a href="https://f-droid.org/en/packages/im.vector.app/" target="_blank" rel="noreferrer">F-Droid</a>.</p></li><li><p><strong>ProtonMail</strong>: Encrypted email service from Switzerland, available on <a href="https://play.google.com/store/apps/details?id=ch.protonmail.android" target="_blank" rel="noreferrer">Android</a> and <a href="https://apps.apple.com/us/app/protonmail-encrypted-email/id979659905" target="_blank" rel="noreferrer">iOS</a>.</p></li></ul><h4 id="specialized-tools-for-security" tabindex="-1">Specialized Tools for Security <a class="header-anchor" href="#specialized-tools-for-security" aria-label="Permalink to &quot;Specialized Tools for Security&quot;">​</a></h4><ul><li><p><strong>TrackerControl</strong> (F-Droid): Monitor and control app data collection.</p></li><li><p><strong>Insular</strong>: Isolate apps or run multiple accounts on <a href="https://f-droid.org/en/packages/com.oasisfeng.island.fdroid/" target="_blank" rel="noreferrer">F-Droid</a>.</p></li></ul><p>[Security] [Guide]</p>',46)])])}const g=a(t,[["render",n]]);export{u as __pageData,g as default};
